.include "rhun.inc"
.bss
.p2align 3
out: .zero SB_SIZE
.text
FN main
    PROLOGUE
    mov r15, [rip + g_mem_live]
    lea r12, [rip + .Lsb64_vectors]
    xor r13d, r13d
.Lsb64_test:
    mov rdi, [r12]
    test rdi, rdi
    jz .Lsb64_api
    mov rsi, [r12 + 8]
    call snippet_base64_decode
    cmp rcx, [r12 + 32]
    jne .Lsb64_fail
    cmp rdx, [r12 + 24]
    jne .Lsb64_fail
    mov r14, rax
    test ecx, ecx
    jz .Lsb64_invalid
    mov rdi, rax
    mov rsi, [r12 + 16]
    call memeq
    test eax, eax
    jz .Lsb64_fail
    mov rdi, r14
    call mem_free
    jmp .Lsb64_next
.Lsb64_invalid:
    test r14, r14
    jnz .Lsb64_fail
.Lsb64_next:
    cmp [rip + g_mem_live], r15
    jne .Lsb64_fail
    inc r13
    add r12, 40
    jmp .Lsb64_test
.Lsb64_api:
    xor edi, edi
    xor esi, esi
    call snippet_base64_decode
    cmp ecx, 1
    jne .Lsb64_fail
    or rax, rdx
    jnz .Lsb64_fail
    xor edi, edi
    mov esi, 5592412
    call snippet_base64_decode
    or rax, rdx
    or rax, rcx
    jnz .Lsb64_fail
    xor edi, edi
    mov esi, 3
    call snippet_base64_decode
    or rax, rdx
    or rax, rcx
    jnz .Lsb64_fail
    cmp [rip + g_mem_live], r15
    jne .Lsb64_fail
    lea rdi, [rip + ok]
    call log_cstr
    xor eax, eax
    EPILOGUE
.Lsb64_fail:
    lea rdi, [rip + fail]
    call log_cstr
    lea rdi, [rip + out]
    mov rsi, r13
    call sb_push_u64
    lea rdi, [rip + out]
    mov esi, 10
    call sb_push_byte
    mov rdi, [rip + out + SB_ptr]
    mov rsi, [rip + out + SB_len]
    call log_write
    mov eax, 1
    EPILOGUE
.section .rodata
ok: .asciz "ok snippet Base64\n"
fail: .asciz "FAIL snippet Base64 "
